import { apiClient } from './client';

// Cover letters (Step 12). Drafts are generated by rules from the user's own
// resume and job description (no language model); saving is a separate step.

export type CoverLetterTone = 'professional' | 'confident' | 'conversational' | 'concise';
export type CoverLetterLength = 'short' | 'standard' | 'detailed';

// Must match the backend's limits.
export const MAX_COVER_LETTER_LENGTH = 10_000;
export const MAX_COVER_LETTER_TITLE = 200;

export const TONES: { id: CoverLetterTone; label: string; description: string }[] = [
  { id: 'professional', label: 'Professional', description: 'Formal and measured.' },
  { id: 'confident', label: 'Confident', description: 'Direct and assured, without overstating.' },
  { id: 'conversational', label: 'Conversational', description: 'Warm and friendly.' },
  { id: 'concise', label: 'Concise', description: 'Short sentences, straight to the point.' },
];
export const LENGTHS: { id: CoverLetterLength; label: string; description: string }[] = [
  { id: 'short', label: 'Short', description: 'About one short page section.' },
  { id: 'standard', label: 'Standard', description: 'Roles, a project and a note on why you want the job.' },
  { id: 'detailed', label: 'Detailed', description: 'Adds more roles, projects, education and certifications.' },
];

export interface GeneratedCoverLetter {
  method: 'rule_based';
  tone: CoverLetterTone;
  length: CoverLetterLength;
  paragraphs: string[];
  text: string;
  wordCount: number;
  placeholders: string[];
  usedFacts: { skills: string[]; experience: string[]; projects: string[]; education: string[]; certifications: string[] };
  notes: string[];
  title: string;
  roleTitle: string;
  companyName: string | null;
  resumeId: string;
  jobDescriptionId: string;
}

export interface CoverLetterSummary {
  id: string;
  title: string;
  roleTitle: string | null;
  companyName: string | null;
  tone: CoverLetterTone;
  length: CoverLetterLength;
  resume: { id: string; filename: string; versionNumber: number } | null;
  jobDescription: { id: string; title: string } | null;
  createdAt: string;
  updatedAt: string;
}

export interface SavedCoverLetter extends CoverLetterSummary {
  content: string;
}

export interface CoverLetterSave {
  title: string;
  content: string;
  tone: CoverLetterTone;
  length: CoverLetterLength;
  roleTitle?: string | null;
  companyName?: string | null;
  resumeId?: string | null;
  jobDescriptionId?: string | null;
}

const json = (method: string, body: unknown): RequestInit => ({ method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });

export const generateCoverLetter = async (input: { resumeId: string; jobDescriptionId: string; tone: CoverLetterTone; length: CoverLetterLength }): Promise<GeneratedCoverLetter> =>
  (await apiClient('/cover-letters/generate', json('POST', input))).data.coverLetter;

export const listCoverLetters = async (): Promise<CoverLetterSummary[]> => (await apiClient('/cover-letters')).data.coverLetters;

export const getCoverLetter = async (id: string): Promise<SavedCoverLetter> =>
  (await apiClient(`/cover-letters/${encodeURIComponent(id)}`)).data.coverLetter;

export const createCoverLetter = async (input: CoverLetterSave): Promise<SavedCoverLetter> =>
  (await apiClient('/cover-letters', json('POST', input))).data.coverLetter;

export const updateCoverLetter = async (id: string, changes: Partial<Pick<CoverLetterSave, 'title' | 'content' | 'tone' | 'length'>>): Promise<SavedCoverLetter> =>
  (await apiClient(`/cover-letters/${encodeURIComponent(id)}`, json('PUT', changes))).data.coverLetter;

export const deleteCoverLetter = async (id: string) => apiClient(`/cover-letters/${encodeURIComponent(id)}`, { method: 'DELETE' });
